package com.yuyutian.mytools.messaging.service;
import com.yuyutian.mytools.messaging.model.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import java.time.Instant;import java.util.List;import static org.assertj.core.api.Assertions.*;
/** 问题反馈迁移测试。 */ @SpringBootTest class SupportFeedbackMigrationServiceTest {@Autowired private SupportFeedbackMigrationService service;
 @Test void shouldDryRunImportReplayConflictAndReconcile(){LegacyFeedbackItem item=item("content");var dry=service.migrate(new LegacyFeedbackBatch("feedback-v1",true,List.of(item)));var apply=service.migrate(new LegacyFeedbackBatch("feedback-v1",false,List.of(item)));var replay=service.migrate(new LegacyFeedbackBatch("feedback-v1",false,List.of(item)));var conflict=service.migrate(new LegacyFeedbackBatch("feedback-v1",false,List.of(item("changed"))));assertThat(dry.accepted()).isEqualTo(1);assertThat(apply.accepted()).isEqualTo(1);assertThat(replay.skipped()).isEqualTo(1);assertThat(conflict.rejected()).isEqualTo(1);FeedbackReconciliation reconciliation=service.reconcile("feedback-v1");assertThat(reconciliation.itemCount()).isEqualTo(1);assertThat(reconciliation.collectionSha256()).isEqualTo(apply.digestSha256());}
 private LegacyFeedbackItem item(String content){return new LegacyFeedbackItem(99,"User","user@example.com","123","BUG","Title",content,"RECEIVED",Instant.EPOCH,Instant.EPOCH);}}
